(function (g) { var L = {"spec":"bim-compiler prompts/VOCAB_MESSAGE_CATALOG.md §19.16 C2","source":"docs/ERPUserGuide.md The standard flow (build_help_pack.js HOWTO)","time":"2026-11-16 19:33:33","links":[{"help":1000000,"window":143,"tab":186,"name":"1 · Sales Order"},{"help":1000001,"window":169,"tab":257,"name":"2 · Shipment"},{"help":1000002,"window":167,"tab":263,"name":"3 · Customer Invoice → AR"},{"help":1000003,"window":195,"tab":330,"name":"4 · Receipt & Allocation"}],
"rows": [
"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000000, '9c8b7259-de7f-5a31-8f39-515f70e2b999', 0, '2026-11-16 19:33:33', 100, 'T', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#1-sales-order', 'Y', '1 · Sales Order', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000000, 1000000, '9c9ac7c9-c759-5df2-aa0b-3b77c4aa9a1f', 0, '2026-11-16 19:33:33', 100, 'Y', NULL, '<p><strong>1 · Sales Order</strong></p><p>Open <b><a href=\"#\" data-help-win=\"143\">Sales Order</a></b> from the menu (⌂ → Sales), create a line or two, and press the <b>Process</b> button (§6) → <b>Complete</b>. Completion is not just a status flip: <code>completeIt</code> fans out into the shipment and invoice that follow it, in the SAME signed op-group.</p>', '2026-11-16 19:33:33', 100)",
"UPDATE ad_tab SET ad_ctxhelp_id=1000000 WHERE ad_tab_id=186 AND ad_ctxhelp_id IS NULL",
"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000001, 'f02888ee-9284-5d0e-ba81-9b2ac95b1d73', 0, '2026-11-16 19:33:33', 100, 'T', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#2-shipment', 'Y', '2 · Shipment', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000001, 1000001, 'acd8379a-62f4-576a-8360-00e12acc2d7d', 0, '2026-11-16 19:33:33', 100, 'Y', NULL, '<p><strong>2 · Shipment</strong></p><p>The <b>Shipment</b> (<code><a href=\"#\" data-help-win=\"169\">M_InOut</a></code>) that Complete generated is a real window of its own (⌂ → Inventory → Shipment) — open it to see the same document from the warehouse side. On-hand for every shipped product drops immediately; the shipment also carries its own GL leg (Cost of Goods Sold against Inventory), not just a paper movement.</p>', '2026-11-16 19:33:33', 100)",
"UPDATE ad_tab SET ad_ctxhelp_id=1000001 WHERE ad_tab_id=257 AND ad_ctxhelp_id IS NULL",
"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000002, 'bd85fcf0-cdba-5d0a-9e6c-6045558f085b', 0, '2026-11-16 19:33:33', 100, 'T', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#3-customer-invoice-ar', 'Y', '3 · Customer Invoice → AR', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000002, 1000002, '06cdc047-08a5-56b7-a4c4-d36502601ed4', 0, '2026-11-16 19:33:33', 100, 'Y', NULL, '<p><strong>3 · Customer Invoice → AR</strong></p><p>The <b><a href=\"#\" data-help-win=\"167\">Invoice</a></b> the same Complete generated posts DR <b>Receivable</b> / CR <b>Revenue</b> (per line) / CR <b>Tax Due</b>. Open <b>Posting Preview</b> on the invoice (any completed document has this) to see that exact journal before you take our word for it — it is the SAME derivation the guide''s Posting-Preview panel runs live, not a separate report-only calculation.</p>', '2026-11-16 19:33:33', 100)",
"UPDATE ad_tab SET ad_ctxhelp_id=1000002 WHERE ad_tab_id=263 AND ad_ctxhelp_id IS NULL",
"INSERT OR IGNORE INTO ad_ctxhelp (ad_client_id, ad_ctxhelp_id, ad_ctxhelp_uu, ad_org_id, created, createdby, ctxtype, description, isactive, name, updated, updatedby) VALUES (0, 1000003, '3c78e5c2-8a11-5d0b-869a-974294624c1a', 0, '2026-11-16 19:33:33', 100, 'T', 'https://red1oon.github.io/BIMCompiler/ERPUserGuide/#4-receipt-allocation', 'Y', '4 · Receipt & Allocation', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg (ad_client_id, ad_ctxhelp_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_uu, ad_org_id, created, createdby, isactive, line, msgtext, updated, updatedby) VALUES (0, 1000003, 1000003, 'b6cef894-e0cc-55d1-9ed3-77269eeac1c9', 0, '2026-11-16 19:33:33', 100, 'Y', NULL, '<p><strong>4 · Receipt &amp; Allocation</strong></p><p>Record the customer''s <b><a href=\"#\" data-help-win=\"195\">Payment</a></b> (⌂ → Sales → Payment) against the invoice, then run <b><a href=\"#\" data-help-win=\"205\">Allocation</a></b> to match payment to invoice. A real allocation is rarely an exact match — it can carry a discount, a write-off, and (because tax rides the discounted portion too) a VAT correction, all in the same posting.</p>', '2026-11-16 19:33:33', 100)",
"UPDATE ad_tab SET ad_ctxhelp_id=1000003 WHERE ad_tab_id=330 AND ad_ctxhelp_id IS NULL",
"INSERT OR IGNORE INTO ad_ctxhelpmsg_trl (ad_client_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_trl_uu, ad_language, ad_org_id, created, createdby, isactive, istranslated, msgtext, updated, updatedby) VALUES (0, 200000, 'd066f8bc-e856-585f-acf2-5e839e31a564', 'es_ES', 0, '2026-11-16 19:33:33', 100, 'Y', 'Y', '<p>¡Bienvenido a iDempiere!</p>\n\n<p>Empiece explorando su espacio de trabajo, manejando datos y personalizando su experiencia.</p>\n\n<p>¿Necesita ayuda? Revise nuestra <a href=\"https://docs.idempiere.org/docs/getting-started\" target=\"_blank\">Getting Started Guide</a> (en inglés).</p>\n', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg_trl (ad_client_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_trl_uu, ad_language, ad_org_id, created, createdby, isactive, istranslated, msgtext, updated, updatedby) VALUES (0, 200000, '17baa900-9385-5a5f-8eff-f84ecbb340c7', 'de_DE', 0, '2026-11-16 19:33:33', 100, 'Y', 'Y', '<p>Willkommen bei iDempiere!</p>\n\n<p>Erkunden Sie Ihren Arbeitsbereich, verwalten Sie Daten und passen Sie Ihre Erfahrung an.</p>\n\n<p>Benötigen Sie Hilfe? Besuchen Sie unsere <a href=\"https://docs.idempiere.org/docs/getting-started\" target=\"_blank\">Erste-Schritte-Anleitung</a>.</p>', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg_trl (ad_client_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_trl_uu, ad_language, ad_org_id, created, createdby, isactive, istranslated, msgtext, updated, updatedby) VALUES (0, 1000000, '082333af-70cc-577f-9131-37baa26d690b', 'de_DE', 0, '2026-11-16 19:33:33', 100, 'Y', 'N', '<p><strong>1 · Auftrag</strong></p><p>Öffnen Sie <b><a href=\"#\" data-help-win=\"143\">Auftrag</a></b> im Menü (⌂ → Vertrieb), legen Sie eine oder zwei Positionen an und drücken Sie die Schaltfläche <b>Verarbeiten</b> (§6) → <b>Fertigstellen</b>. Fertigstellen ist mehr als ein Statuswechsel: <code>completeIt</code> erzeugt die folgende Lieferung und Rechnung in DERSELBEN signierten Operationsgruppe.</p>', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg_trl (ad_client_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_trl_uu, ad_language, ad_org_id, created, createdby, isactive, istranslated, msgtext, updated, updatedby) VALUES (0, 1000001, '727a6170-8774-5579-b648-0304eef4abd1', 'de_DE', 0, '2026-11-16 19:33:33', 100, 'Y', 'N', '<p><strong>2 · Lieferung</strong></p><p>Die <b><a href=\"#\" data-help-win=\"169\">Lieferung (Kunde)</a></b> (<code>M_InOut</code>), die Fertigstellen erzeugt hat, ist ein eigenes Fenster (⌂ → Lager → Lieferung) — öffnen Sie es, um denselben Beleg von der Lagerseite zu sehen. Der Bestand jedes gelieferten Produkts sinkt sofort; die Lieferung hat außerdem eine eigene Buchung (Wareneinsatz gegen Lagerbestand), nicht nur eine Papierbewegung.</p>', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg_trl (ad_client_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_trl_uu, ad_language, ad_org_id, created, createdby, isactive, istranslated, msgtext, updated, updatedby) VALUES (0, 1000002, '8aaddae0-5a41-5390-aa14-af6db2ead1d9', 'de_DE', 0, '2026-11-16 19:33:33', 100, 'Y', 'N', '<p><strong>3 · Kundenrechnung → Forderungen</strong></p><p>Die <b><a href=\"#\" data-help-win=\"167\">Rechnung (Kunde)</a></b>, die dasselbe Fertigstellen erzeugt hat, bucht Soll <b>Forderungen</b> / Haben <b>Erlöse</b> (je Position) / Haben <b>Umsatzsteuer</b>. Öffnen Sie die <b>Buchungsvorschau</b> der Rechnung (jeder fertiggestellte Beleg hat sie), um genau diese Buchung zu sehen, bevor Sie uns glauben — es ist DIESELBE Herleitung, die die Buchungsvorschau des Leitfadens live ausführt, keine separate Berichtsberechnung.</p>', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg_trl (ad_client_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_trl_uu, ad_language, ad_org_id, created, createdby, isactive, istranslated, msgtext, updated, updatedby) VALUES (0, 1000003, 'c741a6ad-1de5-57b8-b8d7-22844a4821eb', 'de_DE', 0, '2026-11-16 19:33:33', 100, 'Y', 'N', '<p><strong>4 · Zahlungseingang und Zuordnung</strong></p><p>Erfassen Sie die <b><a href=\"#\" data-help-win=\"195\">Zahlung</a></b> des Kunden (⌂ → Vertrieb → Zahlung) zur Rechnung und führen Sie dann die <b>Zuordnung</b> aus, um Zahlung und Rechnung abzugleichen. Eine echte Zuordnung passt selten genau — sie kann einen Skonto, eine Abschreibung und (weil die Steuer auch auf den Skontoanteil entfällt) eine Umsatzsteuerkorrektur enthalten, alles in derselben Buchung.</p>', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg_trl (ad_client_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_trl_uu, ad_language, ad_org_id, created, createdby, isactive, istranslated, msgtext, updated, updatedby) VALUES (0, 1000000, '07a07096-925e-532c-bed4-fc45bd3919f1', 'zh_CN', 0, '2026-11-16 19:33:33', 100, 'Y', 'N', '<p><strong>1 · 销售订单</strong></p><p>从菜单（⌂ → 销售）打开<b><a href=\"#\" data-help-win=\"143\">销售订单</a></b>，建一两行，然后按<b>处理</b>按钮（§6）→ <b>完成</b>。完成不只是改变状态：<code>completeIt</code> 会在同一个已签名的操作组里，接着生成后面的出货单和发票。</p>', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg_trl (ad_client_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_trl_uu, ad_language, ad_org_id, created, createdby, isactive, istranslated, msgtext, updated, updatedby) VALUES (0, 1000001, 'f990d08f-bfc2-5424-9d1b-53b75e9d0ca8', 'zh_CN', 0, '2026-11-16 19:33:33', 100, 'Y', 'N', '<p><strong>2 · 出货</strong></p><p>完成时生成的<b><a href=\"#\" data-help-win=\"169\">物料出货(客户/公司)</a></b>（<code>M_InOut</code>）是一个独立的窗口（⌂ → 库存 → 出货）——打开它，从仓库一侧看同一张单据。每个已出货产品的现有库存立即减少；出货单还带有自己的总账分录（销货成本对库存），而不只是纸面上的移动。</p>', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg_trl (ad_client_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_trl_uu, ad_language, ad_org_id, created, createdby, isactive, istranslated, msgtext, updated, updatedby) VALUES (0, 1000002, '5ebe6cba-1ab3-592b-b5d4-15274ee6c29b', 'zh_CN', 0, '2026-11-16 19:33:33', 100, 'Y', 'N', '<p><strong>3 · 客户发票 → 应收</strong></p><p>同一次完成生成的<b><a href=\"#\" data-help-win=\"167\">发票(客户/公司)</a></b>记账：借<b>应收账款</b> / 贷<b>收入</b>（按行）/ 贷<b>应交税金</b>。在发票上打开<b>记账预览</b>（任何已完成的单据都有）——先看这张分录，再相信我们的说法；它和指南里的记账预览面板实时运行的是同一个推导，不是单独的报表计算。</p>', '2026-11-16 19:33:33', 100)",
"INSERT OR IGNORE INTO ad_ctxhelpmsg_trl (ad_client_id, ad_ctxhelpmsg_id, ad_ctxhelpmsg_trl_uu, ad_language, ad_org_id, created, createdby, isactive, istranslated, msgtext, updated, updatedby) VALUES (0, 1000003, 'cafbddb2-1819-5c90-82e3-214dbe381a81', 'zh_CN', 0, '2026-11-16 19:33:33', 100, 'Y', 'N', '<p><strong>4 · 收款与分配</strong></p><p>针对发票记录客户的<b><a href=\"#\" data-help-win=\"195\">付款</a></b>（⌂ → 销售 → 付款），然后运行<b>分配</b>，把付款和发票对上。真实的分配很少正好相等——它可以带折扣、核销，以及（因为税也跟着折扣部分走）增值税调整，全部在同一笔记账里。</p>', '2026-11-16 19:33:33', 100)"]};
  if (typeof module !== "undefined" && module.exports) module.exports = L; g.AD_CTXHELP_APP_ROWS = L; })(typeof window !== "undefined" ? window : globalThis);
